float

CheckSum(const float *matrix, const int width, const int height)

{

    int i, j;

    float s1, s2;

    for (i = 0, s1 = 0; i < width; i++) {

        for (j = 0, s2 = 0; j < height; j++) {

            s2 += matrix[i * width + j];

        }

        s1 += s2;

    }

    return s1;

}

